#!/usr/bin/env node
/**
 * Finds `not in` guards that a NULL value can walk straight through.
 *
 * Two classes matter. Authorization guards (role lookups, `*role` variables, and
 * any comparison against a role value) let a caller act without permission when
 * the role is NULL, so those fail the build. Validation guards reject a bad
 * parameter value; a NULL parameter skips the check instead, which is a
 * correctness bug rather than an access bug, so those are reported and only
 * fail when `--strict-validation` is passed.
 *
 * 0052, 0054, 0055 and 0056 were generated by this script, so the check and the
 * fixes cannot drift.
 *
 * Usage:
 *   node scripts/sql-role-guard-audit.mjs                     # role guards only
 *   node scripts/sql-role-guard-audit.mjs --emit file.sql     # role fix migration
 *   node scripts/sql-role-guard-audit.mjs --validation        # list nullable checks
 *   node scripts/sql-role-guard-audit.mjs --strict-validation # exit 1 if any remain
 *   node scripts/sql-role-guard-audit.mjs --emit-validation file.sql
 *   node scripts/sql-role-guard-audit.mjs --dir other/dir     # scan another tree
 */

import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import path from "node:path";

const dirIndex = process.argv.indexOf("--dir");
const MIGRATIONS = dirIndex === -1
  ? path.join(process.cwd(), "supabase/migrations")
  : path.resolve(process.argv[dirIndex + 1]);
const ROLE_FUNCTION = /public\.(?:app_project_role|workspace_role)\s*\(/;
const ROLE_NAME = /(?:^|_)(?:actor_)?role$/;
const ROLE_WORDS = ["owner", "admin", "maintainer", "member", "contributor", "reviewer", "viewer"];
const DEFINITION =
  /create or replace function (public\.[a-z_0-9]+)\s*\(([\s\S]*?)\)\s*returns[\s\S]*?\$\$([\s\S]*?)\$\$;/g;

function collect() {
  const latest = new Map();
  for (const file of readdirSync(MIGRATIONS).filter((name) => name.endsWith(".sql")).sort()) {
    const sql = readFileSync(path.join(MIGRATIONS, file), "utf8");
    for (const match of sql.matchAll(DEFINITION)) {
      latest.set(match[1], { file, full: match[0], args: match[2], body: match[3] });
    }
  }
  return latest;
}

/** The expression immediately before `not in`, which may be a call like `f(x)`. */
function operandBefore(text, index) {
  let end = index;
  while (end > 0 && /\s/.test(text[end - 1])) end -= 1;
  let start = end;
  if (text[end - 1] === ")") {
    let depth = 0;
    for (let i = end - 1; i >= 0; i -= 1) {
      if (text[i] === ")") depth += 1;
      else if (text[i] === "(") {
        depth -= 1;
        if (depth === 0) {
          start = i;
          break;
        }
      }
    }
    while (start > 0 && /[\w.]/.test(text[start - 1])) start -= 1;
  } else {
    while (start > 0 && /[\w.]/.test(text[start - 1])) start -= 1;
  }
  return { operand: text.slice(start, end), start };
}

/** Closing index of the value list that follows `not in`. */
function valueListEnd(text, index) {
  let depth = 0;
  for (let i = index; i < text.length; i += 1) {
    if (text[i] === "(") depth += 1;
    else if (text[i] === ")") {
      depth -= 1;
      if (depth === 0) return i + 1;
    }
  }
  return text.length;
}

/**
 * A guard is about roles when it reads a variable or parameter named *role, when
 * it calls a role lookup, or when it compares against a role value. The last
 * case catches a membership kept in a differently named variable.
 */
function isRoleGuard(operand, values) {
  const bare = operand.replace(/\s*\([\s\S]*$/, "");
  if (ROLE_NAME.test(bare) || ROLE_FUNCTION.test(operand)) return true;
  return ROLE_WORDS.some((word) => values.includes(`'${word}'`));
}

/** True when the operand cannot be null at this point in the body. */
function rejectsNull(body, condition, operand, index) {
  const escaped = operand.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  if (/coalesce\s*\(/i.test(operand)) return true;
  if (new RegExp(`${escaped}\\s+is null`, "i").test(condition)) return true;

  const prefix = body.slice(0, index);
  if (new RegExp(`${escaped}\\s+is null`, "i").test(prefix)) return true;

  if (!operand.includes("(")) {
    const assignments = [...prefix.matchAll(new RegExp(`\\b${escaped}\\b[^;]*?:=\\s*([^;]*);`, "g"))];
    const last = assignments.at(-1)?.[1] ?? "";
    if (/coalesce\s*\(/i.test(last)) return true;
  }
  return false;
}

/** Guard sites a NULL can pass, split into authorization and validation. */
function analyse({ body }) {
  const role = [];
  const validation = [];
  for (const statement of body.matchAll(/(?<!end )\bif\b([\s\S]*?)\bthen\b/g)) {
    const condition = statement[1];
    const conditionStart = statement.index + statement[0].indexOf(condition);
    const collapsed = condition.trim().replace(/\s+/g, " ");

    for (const site of condition.matchAll(/not in\s*\(/gi)) {
      const { operand, start } = operandBefore(condition, site.index);
      if (!operand) continue;
      if (rejectsNull(body, condition, operand, conditionStart + start)) continue;
      const values = condition.slice(site.index, valueListEnd(condition, site.index));
      const entry = { operand, index: conditionStart + start, condition: collapsed };
      if (isRoleGuard(operand, values)) role.push(entry);
      else if (/^p_[a-z_]+$/.test(operand)) validation.push({ ...entry, kind: "parameter" });
      else if (/^v_[a-z_]+$/.test(operand)) validation.push({ ...entry, kind: "local" });
    }

    for (const site of condition.matchAll(/([a-z_]\w*)\s*<>\s*'[a-z_]+'/gi)) {
      const operand = site[1];
      if (!/^(p|v)_/.test(operand)) continue;
      if (isRoleGuard(operand, site[0])) continue;
      if (rejectsNull(body, condition, operand, conditionStart + site.index)) continue;
      validation.push({
        operand,
        index: conditionStart + site.index,
        condition: collapsed,
        kind: "inequality",
      });
    }
  }
  return { role, validation };
}

/** Wraps each guard as `(x is null or x not in (...))`, parens included. */
function applyFindings(full, body, findings) {
  const bodyStart = full.indexOf(body);
  for (const finding of [...findings].sort((a, b) => b.index - a.index)) {
    const at = bodyStart + finding.index;
    const rest = full.slice(at);
    if (finding.kind === "inequality") {
      const literal = rest.slice(0, rest.indexOf("'", finding.operand.length));
      const end = rest.indexOf("'", literal.length + 1) + 1;
      const site = rest.slice(0, end);
      full = full.slice(0, at) + `(${finding.operand} is null or ${site})` + full.slice(at + end);
      continue;
    }
    const open = rest.indexOf("(", finding.operand.length);
    const close = valueListEnd(rest, open);
    const site = rest.slice(0, close);
    full = full.slice(0, at) + `(${finding.operand} is null or ${site})` + full.slice(at + close);
  }
  return full;
}

function patchRole(definition) {
  const { role } = analyse(definition);
  let full = applyFindings(definition.full, definition.body, role);
  const inequality = /if\s+(public\.app_project_role\([^)]*\))\s*<>\s*'owner'\s+then/g;
  full = full.replace(inequality, "if $1 is distinct from 'owner' then");
  return { full, findings: role };
}

function patchValidation(definition) {
  const { validation } = analyse(definition);
  return { full: applyFindings(definition.full, definition.body, validation), findings: validation };
}

const latest = collect();
const emitTo = (() => {
  const index = process.argv.indexOf("--emit");
  return index === -1 ? null : process.argv[index + 1];
})();
const emitValidationTo = (() => {
  const index = process.argv.indexOf("--emit-validation");
  return index === -1 ? null : process.argv[index + 1];
})();
const wantsValidation = process.argv.includes("--validation");
const strictValidation = process.argv.includes("--strict-validation");

const roleChanged = [];
const validationChanged = [];
const validationSites = [];
for (const [name, definition] of [...latest].sort(([a], [b]) => a.localeCompare(b))) {
  const role = patchRole(definition);
  if (role.full !== definition.full) roleChanged.push({ name, file: definition.file, ...role });
  for (const site of analyse(definition).validation) {
    validationSites.push({ ...site, func: name, file: definition.file });
  }
  const parameter = patchValidation(definition);
  if (parameter.full !== definition.full) validationChanged.push({ name, file: definition.file, ...parameter });
}

const header = (title, body) => `-- GET TO IT — ${title}\n${body}\n-- Generated by scripts/sql-role-guard-audit.mjs, so the check and the fix share one rule set.\n\n`;

if (emitTo) {
  const text = header(
    "reject a caller whose role check cannot be decided.",
    `--\n-- A guard such as\n--\n--   if public.workspace_role(id) not in ('owner', 'admin') then ...\n--   if p_kind = 'agent' and v_role not in ('owner', 'maintainer') then ...\n--\n-- is NULL, not false, when the role is NULL, so the guard never runs. Each guard\n-- now tests its role source for null first, parenthesised so compound precedence\n-- is unchanged.\n`,
  );
  writeFileSync(emitTo, text + roleChanged.map((entry) => entry.full).join("\n\n") + "\n");
  console.log(`wrote ${emitTo}: ${roleChanged.length} functions, ${roleChanged.reduce((n, c) => n + c.findings.length, 0)} guard sites`);
  process.exit(0);
}

if (emitValidationTo) {
  const sites = validationChanged.reduce((total, entry) => total + entry.findings.length, 0);
  const text = header(
    "reject a parameter that is missing where a value list is required.",
    `--\n-- A guard such as \`if p_decision not in ('approved', 'rejected') then\` is NULL,\n-- not false, when the parameter is missing, so the check never runs and the NULL\n-- travels into the statement that follows. Each guard now rejects a missing\n-- parameter explicitly instead of relying on a column constraint to catch it.\n--\n-- Validation only: these guards decide whether input is well formed, not whether\n-- the caller may act.\n`,
  );
  writeFileSync(emitValidationTo, text + validationChanged.map((entry) => entry.full).join("\n\n") + "\n");
  console.log(`wrote ${emitValidationTo}: ${validationChanged.length} functions, ${sites} guard sites`);
  for (const entry of validationChanged) for (const site of entry.findings) console.log(`  ${entry.name}: ${site.condition}`);
  process.exit(0);
}

if (roleChanged.length > 0) {
  const sites = roleChanged.reduce((total, entry) => total + entry.findings.length, 0);
  console.error(`✖ ${sites} role guard(s) can pass when the role is null, in ${roleChanged.length} function(s):`);
  for (const entry of roleChanged) {
    console.error(`  ${entry.file} :: ${entry.name}`);
    for (const finding of entry.findings) console.error(`      ${finding.condition}`);
  }
  console.error("Add `is null or`, or check the role for null before it.");
  process.exit(1);
}

const byKind = (kind) => validationSites.filter((site) => site.kind === kind);

if (wantsValidation || strictValidation) {
  console.log(`${validationSites.length} guard(s) can pass when the value is null:`);
  for (const kind of ["parameter", "local", "inequality"]) {
    const group = byKind(kind);
    console.log(`  ${kind}: ${group.length}`);
    if (wantsValidation) {
      for (const site of group) {
        console.log(`    ${site.file} :: ${site.func}`);
        console.log(`        ${site.condition}`);
      }
    }
  }
  if (strictValidation && validationSites.length > 0) {
    console.error("✖ nullable validation guards remain; add `is null or` or prove the column rejects null.");
    process.exit(1);
  }
} else if (validationSites.length > 0) {
  console.log(`ℹ ${validationSites.length} guard(s) can pass when the value is null; run with --validation to list them.`);
}

console.log(`✔ ${latest.size} functions scanned; every role guard rejects a null role.`);
